  inv("specializedAdjunctive", "Ankle-brachial index (ABI)", "Doppler BP ratio", "Peripheral artery disease", "0.9–1.3", "Below 0.9", "Refer for vascular evaluation (ICMR STW).", "df", DF),
  inv("specializedAdjunctive", "Probe-to-bone test", "Sterile blunt probe", "Osteomyelitis", "Bone not reached", "Bone felt through the ulcer", "Sensitivity 0.87, specificity 0.83; combine with X-ray and ESR (IWGDF Rec. 7).", "iwgdf", "Recommendation 7"),
